-- mod-classless-wildcard: make every class-locked skill line valid for all
-- race/class combos, so the core's race/class skill validation
-- (Player::CheckSkillLearnedBySpell / Player::_LoadSkills) stops deleting
-- cross-class spells and weapon skills taught by the classless system.
-- AzerothCore loads these rows on top of SkillRaceClassInfo.dbc at startup;
-- RaceMask = 0 and ClassMask = 0 mean 'no restriction'. Flags/MinLevel/
-- SkillTierID/SkillCostIndex are copied from each skill's most permissive
-- original row. Race-locked lines (languages, racials) are left untouched.
-- Requires a worldserver restart to take effect.
DELETE FROM `skillraceclassinfo_dbc` WHERE `ID` BETWEEN 990000 AND 990999;
